    local function VM_l1l1(d, k, m)
        local R_Ol01Ol = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_Ol01Ol, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_Ol01Ol)
    end

    -- Execution Guard
    local F_OllIO = loadstring(VM_l1l1(B_0l0O0l1l, 5, 5))
    if F_OllIO then
        F_OllIO(...)
    end
end)(...)
